#!/usr/bin/env python3
"""Classify a strict 2019 source-only cohort; do not create correction proposals."""
import csv,json,math
from collections import Counter
from datetime import datetime,timezone
from pathlib import Path
R=Path(__file__).resolve().parents[1]
rows=json.loads((R/'data/source-only-pilot-2019-strict-copy-concordance.json').read_text());rows.sort(key=lambda x:x['dateTime'])
def utc(t):return datetime.fromtimestamp(t,timezone.utc).isoformat().replace('+00:00','Z')
blocks=[];cur=[]
for r in rows:
 if cur and r['dateTime']==cur[-1]['dateTime']+300:cur.append(r)
 else:
  if cur:blocks.append(cur)
  cur=[r]
if cur:blocks.append(cur)
deltas=[abs(r[k]-r['old_temp']) for r in rows for k in ('prev_temp','next_temp') if r[k] is not None]
agg=json.loads((R/'data/source_only_2009_2020_cross_archive_grouped.json').read_text())
third=sum(r['timestamp_count'] for r in agg if r['utc_year']==2019 and r['interval_min']==5 and r['usUnits']==17 and r['on_5m_grid']==1 and r['both_copies']==1 and r['concordance']=='ALL_PRIMARY_EQUAL' and all(r[k]==1 for k in ('old_temp_present','wh_temp_present','old_rh_present','wh_rh_present','old_rain_present','wh_rain_present','old_rainrate_present','wh_rainrate_present','old_wind_present','wh_wind_present')) and r['has_pocasi_old']==0)
assert third==len(rows)==233
summary={'scope':'2019 strict exact-grid source-only full-row cohort','classification_counts':{'RESTORED':0,'ESTIMATED':0,'REVIEW_REQUIRED':len(rows),'MISSING':0},'target_rows_in_reconstruction':0,'target_change_history_events':0,'change_history_basis':'Exhaustive indexed audit covered all 207,182 source-only timestamps and found zero reconstruction_changes events.','source_rows':{'old_weewx':len(rows),'weewx_WH1080':len(rows)},'source_units':{'old_weewx':sorted({r['old_units'] for r in rows}),'weewx_WH1080':sorted({r['wh_units'] for r in rows})},'intervals':{'old_weewx':sorted({r['old_interval'] for r in rows}),'weewx_WH1080':sorted({r['wh_interval'] for r in rows})},'all_five_primary_fields_nonnull':True,'exact_copy_matches':{f:sum(r['old_'+k]==r['wh_'+k] for r in rows) for f,k in [('outTemp','temp'),('outHumidity','rh'),('rain','rain'),('rainRate','rainrate'),('windSpeed','wind')]},'source_ranges':{f:{'min':min(r['old_'+k] for r in rows),'max':max(r['old_'+k] for r in rows),'zero_count':sum(r['old_'+k]==0 for r in rows)} for f,k in [('outTemp','temp'),('outHumidity','rh'),('rain','rain'),('rainRate','rainrate'),('windSpeed','wind')]},'blocks':[{'n':len(b),'start_utc':utc(b[0]['dateTime']),'end_utc':utc(b[-1]['dateTime']),'elapsed_minutes':(b[-1]['dateTime']-b[0]['dateTime'])/60,'distinct_values':{f:len({r['old_'+k] for r in b}) for f,k in [('outTemp','temp'),('outHumidity','rh'),('rain','rain'),('rainRate','rainrate'),('windSpeed','wind')]}} for b in blocks],'neighbor_temperature_delta_c':{'n':len(deltas),'max':round(max(deltas),3),'p95_empirical':round(sorted(deltas)[math.ceil(.95*len(deltas))-1],3),'count_gt_2c':sum(x>2 for x in deltas),'count_gt_5c':sum(x>5 for x in deltas)},'third_archive_exact_rows':0,'decision':'REVIEW_REQUIRED_SOURCE_LINEAGE','review_reasons':['Historical export role and per-row identity not authenticated; two exact copies may share lineage.','No exact row in pocasi-loucka.eu_old for this strict on-grid cohort; no third archive corroboration.','Plausibility screen found no zero outTemp/RH; only two neighbor ΔT values exceed 2.0 C and none exceed 5 C.'], 'correction_operations_created':0,'protected_scope':'2019 only; Q1 2018 not queried; 2021 not queried'}
(R/'data/source_only_pilot_2019_validation.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n')
fields=list(rows[0].keys())+['dateTime_utc','classification','reason_codes']
with (R/'reports/2026-11-13-source-only-pilot-2019-row-evidence.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in rows:
  q=dict(r);q['dateTime_utc']=utc(r['dateTime']);q['classification']='REVIEW_REQUIRED'
  q['reason_codes']='SOURCE_LINEAGE_UNAUTHENTICATED;NO_THIRD_ARCHIVE_CONFIRMATION';w.writerow(q)
lines=['# Source-only pilot lane 2019 — physically plausible, provenance blocked','',f"**Rozsah:** {len(rows)} source-only UTC targetů v roce 2019 splňuje strict screen: oba archivy, `usUnits=17`, interval 5, přesný 300s grid, všech pět primárních veličin non-NULL a přesně shodných; reconstruction row na cílovém timestampu chybí.",'',f"**RESTORED 0 / ESTIMATED 0 / REVIEW_REQUIRED {len(rows)} / MISSING 0.** Tato kohorta je dosud nejvhodnější lineage-pilotní větev, nikoli schválený pilot. Dva archivy nejsou prokázány jako nezávislé a chybí ověřený export-role/physical-sensor link.",'','## Row-level screen','', '| Atribut | Výsledek |','|---|---:|']
for key,label in [('outTemp','outTemp'),('outHumidity','outHumidity'),('rain','rain'),('rainRate','rainRate'),('windSpeed','windSpeed')]:
 v=summary['source_ranges'][key];lines.append(f"| {label}: min–max; nula | {v['min']}–{v['max']}; {v['zero_count']} |")
lines += [f"| Exact source-copy equality | "+'; '.join(f"{k} {v}/{len(rows)}" for k,v in summary['exact_copy_matches'].items()),f"| Target archive rows / change events | 0 / 0 (history event audit inherited from exhaustive 207,182 timestamp join) |",f"| Source-only blocks | "+'; '.join(f"n={b['n']}: {b['start_utc']}–{b['end_utc']} ({b['elapsed_minutes']} elapsed min)" for b in summary['blocks']),f"| Adjacent temperature changes | max {summary['neighbor_temperature_delta_c']['max']} °C; >2 °C: {summary['neighbor_temperature_delta_c']['count_gt_2c']}; >5 °C: 0 |",'| Exact rows in third source archive `pocasi-loucka.eu_old` | 0 for this strict on-grid cohort |','', 'The values vary within the two largest contiguous blocks and pass broad physical range screening; this does not authenticate their origin. The longest contiguous candidate window contains 192 rows (15 h 55 min elapsed; 16 h at a nominal 5-minute row cadence). Two adjacent temperature differences exceed 2 °C (maximum 2.533 °C), with no greater-than-5 °C jump. No target-level history events were present in the exhaustive source-only history join.','', '## Pilot decision and required evidence','', 'A value-level restoration still requires a dated WeeWX configuration/export/backup chain linking `old_weewx`/`weewx_WH1080` to the 2009 station/sensor epoch, timestamp and unit semantics, plus source-quality and calibration context. The public station history is not a database-export lineage document. Until this appears, keep all 233 as REVIEW_REQUIRED; do not create a batch or duplicate insert. If authenticated, review each variable separately and recheck current target state/history.','', 'No 2021 or Q1 2018 data is included. Database access was SELECT only.','', 'SQL: `sql/readonly/source_only_pilot_2019_strict_copy_cohort.sql`; script: `scripts/analyze_source_only_pilot_2019.py`; validator: `scripts/validate_source_only_pilot_2019.py`; detailed evidence: `reports/2026-11-13-source-only-pilot-2019-row-evidence.csv`.']
(R/'reports/2026-11-13-source-only-pilot-2019-strong-concordance.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'n':len(rows),'blocks':[{'n':len(b),'start':utc(b[0]['dateTime']),'end':utc(b[-1]['dateTime'])} for b in blocks],'classification':'REVIEW_REQUIRED','max_neighbor_delta':summary['neighbor_temperature_delta_c']['max']}))
